import SwiftUI
struct LoginView:View{@EnvironmentObject var session:SessionStore;@State private var email="";@State private var password="";@State private var displayName="";@State private var registering=false;@State private var loading=false
 var body:some View{NavigationStack{Form{Picker("İşlem",selection:$registering){Text("Giriş").tag(false);Text("Kayıt").tag(true)}.pickerStyle(.segmented);Section{if registering{TextField("Adınız",text:$displayName)};TextField("E-posta",text:$email).textInputAutocapitalization(.never).keyboardType(.emailAddress);SecureField("Parola",text:$password)}Section{Button(loading ? "İşleniyor…":registering ? "Hesap Oluştur":"Giriş Yap"){loading=true;Task{if registering{await session.register(email:email,password:password,displayName:displayName)}else{await session.login(email:email,password:password)};loading=false}}.disabled(email.isEmpty||password.isEmpty||(registering&&displayName.isEmpty)||loading)}if registering{Text("Parola en az 12 karakter olmalıdır.").font(.caption).foregroundStyle(.secondary)}if let message=session.errorMessage{Text(message).foregroundStyle(.red)}}.navigationTitle(Configuration.displayName)}}
